import re

_UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'week': 604800, 'weeks': 604800,
}

_BARE_INT_RE = re.compile(r'^\d+$')
_COMPONENT_LIST_RE = re.compile(r'^(?:\d+(?:\.\d+)?\s*[a-zA-Z]+\s*)+$')
_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)')
_ISO_RE = re.compile(
    r'^P(?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?'
    r'(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?$'
)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("empty input")

    stripped = text.strip()
    if not stripped:
        raise ValueError("empty input")

    # Bare non-negative integer, meaning seconds.
    if _BARE_INT_RE.match(stripped):
        return int(stripped)

    # ISO 8601 duration.
    if stripped.upper().startswith('P'):
        match = _ISO_RE.match(stripped.upper())
        if not match or stripped.upper() == 'P':
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        if all(g is None for g in match.groups()):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        weeks, days, hours, minutes, seconds = (
            float(g) if g is not None else 0.0 for g in match.groups()
        )
        total = (
            weeks * _UNIT_SECONDS['w']
            + days * _UNIT_SECONDS['d']
            + hours * _UNIT_SECONDS['h']
            + minutes * _UNIT_SECONDS['m']
            + seconds * _UNIT_SECONDS['s']
        )
        return round(total)

    # Clock notation: hh:mm:ss or mm:ss
    if ':' in stripped:
        parts = stripped.split(':')
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock duration: {text!r}")
        try:
            values = [float(p) for p in parts]
        except ValueError:
            raise ValueError(f"invalid clock duration: {text!r}")
        if any(v < 0 for v in values):
            raise ValueError(f"negative duration: {text!r}")
        if len(values) == 3:
            hours, minutes, seconds = values
        else:
            hours = 0
            minutes, seconds = values
        total = hours * 3600 + minutes * 60 + seconds
        return round(total)

    # Number+unit components, optionally separated by spaces.
    if _COMPONENT_LIST_RE.match(stripped):
        total = 0.0
        pos = 0
        for match in _COMPONENT_RE.finditer(stripped):
            number_str, unit_str = match.groups()
            unit_key = unit_str.lower()
            if unit_key not in _UNIT_SECONDS:
                raise ValueError(f"unknown unit: {unit_str!r}")
            total += float(number_str) * _UNIT_SECONDS[unit_key]
        return round(total)

    raise ValueError(f"cannot parse duration: {text!r}")

